    static var summary: String { L("Fixes words typed in the wrong keyboard layout.", [.ru: "Исправляет слова, набранные не в той раскладке.", .es: "Corrige palabras escritas en la distribución equivocada.", .fr: "Corrige les mots tapés dans la mauvaise disposition.", .de: "Korrigiert Wörter, die in der falschen Belegung getippt wurden.", .ja: "誤った配列で入力した単語を修正します。", .zh: "修正用错误键盘布局输入的单词。", .pt: "Corrige palavras digitadas no layout errado."]) }
    static var automatic: String { L("Fix as I type", [.ru: "Исправлять по ходу набора", .es: "Corregir mientras escribo", .fr: "Corriger pendant la saisie", .de: "Beim Tippen korrigieren", .ja: "入力しながら修正", .zh: "输入时自动修正", .pt: "Corrigir enquanto digito"]) }
    static var automaticNote: String { L("A word is only changed when it is not a word as typed and is one once swapped. Anything valid is left alone.", [.ru: "Слово меняется, только если само по себе оно не слово, а после смены раскладки словом становится. Всё осмысленное остаётся как есть.", .es: "Una palabra solo cambia si no es palabra tal como se escribió y sí lo es al convertirla. Lo válido no se toca.", .fr: "Un mot n’est changé que s’il n’en est pas un tel quel et en devient un une fois converti. Ce qui est valide reste.", .de: "Ein Wort wird nur geändert, wenn es so getippt keines ist und nach dem Tausch eines wird. Gültiges bleibt.", .ja: "入力どおりでは単語でなく、変換すると単語になる場合のみ置き換えます。正しいものはそのままです。", .zh: "只有当按原样不是单词、转换后才是单词时才替换。有效的内容不会被改动。", .pt: "Uma palavra só muda se não for palavra como digitada e passar a ser após a troca. O que é válido fica."]) }
    static var needsAccessibility: String { L("Without Accessibility Helm cannot see what you type, and this does nothing.", [.ru: "Без универсального доступа Helm не видит набранное, и это не работает.", .es: "Sin Accesibilidad, Helm no ve lo que escribes y esto no funciona.", .fr: "Sans l’Accessibilité, Helm ne voit pas ce que vous tapez et ceci ne fait rien.", .de: "Ohne Bedienungshilfen sieht Helm nicht, was du tippst — das hier bleibt wirkungslos.", .ja: "アクセシビリティがないと入力内容を読み取れず、この機能は動作しません。", .zh: "没有辅助功能权限，Helm 无法读取输入，此功能不起作用。", .pt: "Sem Acessibilidade o Helm não vê o que você digita e isto não faz nada."]) }
    static var suspended: String { L("Paused — the system is in secure input.", [.ru: "Приостановлено — система в защищённом вводе.", .es: "En pausa: el sistema está en entrada segura.", .fr: "En pause — le système est en saisie sécurisée.", .de: "Pausiert — das System ist in sicherer Eingabe.", .ja: "一時停止中 — システムがセキュア入力です。", .zh: "已暂停——系统处于安全输入状态。", .pt: "Pausado — o sistema está em entrada segura."]) }
    static var exceptions: String { L("Never change these words", [.ru: "Никогда не менять эти слова", .es: "Nunca cambiar estas palabras", .fr: "Ne jamais changer ces mots", .de: "Diese Wörter nie ändern", .ja: "これらの単語は変更しない", .zh: "从不修改这些词", .pt: "Nunca alterar estas palavras"]) }
    static var exceptionsHint: String { L("One per line.", [.ru: "По одному в строке.", .es: "Uno por línea.", .fr: "Un par ligne.", .de: "Eines pro Zeile.", .ja: "1行に1つ。", .zh: "每行一个。", .pt: "Um por linha."]) }
    static var triggers: String { L("When to fix", [.ru: "Когда исправлять", .es: "Cuándo corregir", .fr: "Quand corriger", .de: "Wann korrigieren", .ja: "修正するタイミング", .zh: "何时修正", .pt: "Quando corrigir"]) }
    static var triggersHint: String { L("A word is checked when you finish it this way. Moving the caret or clicking elsewhere never converts — by then you have moved on.", [.ru: "Слово проверяется, когда вы закончили его одним из этих способов. Перемещение курсора или клик в другом месте не запускают проверку: к этому моменту вы уже заняты другим.", .es: "La palabra se revisa cuando la terminas así. Mover el cursor o hacer clic en otro sitio nunca convierte: ya te has ido.", .fr: "Le mot est vérifié quand vous le terminez ainsi. Déplacer le curseur ou cliquer ailleurs ne convertit jamais : vous êtes déjà parti.", .de: "Ein Wort wird geprüft, wenn du es so beendest. Cursor bewegen oder woanders klicken konvertiert nie — dann bist du schon weiter.", .ja: "この方法で単語を終えたときに判定します。カーソル移動や他所のクリックでは変換しません。既に離れているためです。", .zh: "以这些方式结束单词时才会判断。移动光标或点击别处从不转换——那时你已经离开了。", .pt: "A palavra é verificada quando você a termina assim. Mover o cursor ou clicar em outro lugar nunca converte — você já saiu."]) }
