    static var introTitle: String { L("Keyboard", [.ru: "Клавиатура", .es: "Teclado", .fr: "Clavier", .de: "Tastatur", .ja: "キーボード", .zh: "键盘", .pt: "Teclado"]) }
    static var introSubtitle: String { L("Before it starts changing what you type.", [.ru: "Что оно делает с вашим текстом — до того, как начнёт.", .es: "Antes de que empiece a cambiar lo que escribes.", .fr: "Avant qu’il ne commence à modifier ce que vous tapez.", .de: "Bevor es anfängt, dein Getipptes zu ändern.", .ja: "入力した文字を書き換える前に。", .zh: "在它开始改动你输入的文字之前。", .pt: "Antes de começar a mudar o que você digita."]) }
    static var introWhat: String { L("Type ghbdtn in the wrong layout and it becomes привет, with the input source switching to match.", [.ru: "Набрали ghbdtn, забыв переключить раскладку, — Helm заменит это на «привет» и переключит раскладку сам.", .es: "Escribe ghbdtn en la distribución equivocada y se convierte en привет; la fuente de entrada cambia con él.", .fr: "Tapez ghbdtn dans la mauvaise disposition : le mot devient привет, et la source de saisie suit.", .de: "Tippe ghbdtn in der falschen Belegung, und daraus wird привет — die Eingabequelle wechselt mit.", .ja: "配列を切り替え忘れて ghbdtn と入力すると、привет に直り、入力ソースも切り替わります。", .zh: "用错布局输入 ghbdtn，它会变成 привет，输入法也随之切换。", .pt: "Digite ghbdtn no layout errado e vira привет, com a fonte de entrada acompanhando."]) }
    static var introWhen: String { L("Only when what you typed is not a word and becomes one once the layout is switched. Anything that is already a word is left alone.", [.ru: "Только если набранное — не слово, а после смены раскладки словом становится. Всё, что осмысленно как есть, остаётся нетронутым.", .es: "Solo cuando lo escrito no es una palabra y sí lo es al cambiar de distribución. Lo que ya es una palabra no se toca.", .fr: "Uniquement si ce que vous avez tapé n’est pas un mot et en devient un une fois la disposition changée. Ce qui est déjà un mot reste intact.", .de: "Nur wenn das Getippte kein Wort ist und nach dem Belegungswechsel eines wird. Was schon ein Wort ist, bleibt unberührt.", .ja: "入力どおりでは単語でなく、配列を切り替えると単語になる場合だけです。すでに単語であるものには触れません。", .zh: "仅当按原样不是单词、切换布局后才是单词时才会改。已经是单词的一律不动。", .pt: "Só quando o que você digitou não é palavra e passa a ser depois de trocar o layout. O que já é palavra fica intacto."]) }
    static var introWhere: String { L("Never in terminals, password fields or password managers — there a strange-looking word is usually the right one.", [.ru: "Никогда — в терминалах, полях пароля и менеджерах паролей: там непонятный набор символов чаще всего и есть то, что нужно.", .es: "Nunca en terminales, campos de contraseña ni gestores de contraseñas: ahí una palabra rara suele ser la correcta.", .fr: "Jamais dans un terminal, un champ de mot de passe ou un gestionnaire de mots de passe : là, un mot bizarre est en général le bon.", .de: "Nie in Terminals, Passwortfeldern oder Passwortmanagern — dort ist ein seltsam aussehendes Wort meist das richtige.", .ja: "ターミナル、パスワード欄、パスワード管理アプリでは動きません。そこでは不可解な文字列こそが正しい入力です。", .zh: "在终端、密码框和密码管理器中从不介入——那里看起来奇怪的字符往往正是要输入的。", .pt: "Nunca em terminais, campos de senha ou gerenciadores de senha — ali uma palavra estranha costuma ser a certa."]) }
    static var introUndo: String { L("Every change can be undone — set the shortcut below. And there is a field on this page to try it in, before it touches anything real.", [.ru: "Любую замену можно отменить — горячая клавиша настраивается ниже. А ещё на этой странице есть поле, где всё можно попробовать до того, как модуль коснётся настоящего текста.", .es: "Cada cambio se puede deshacer — el atajo se configura abajo. Y en esta página hay un campo para probarlo antes de que toque nada real.", .fr: "Tout changement peut être annulé — le raccourci se règle ci-dessous. Et cette page contient un champ pour essayer, avant que rien de réel ne soit touché.", .de: "Jede Änderung lässt sich zurücknehmen — der Kurzbefehl wird unten festgelegt. Und auf dieser Seite gibt es ein Feld zum Ausprobieren, bevor echter Text berührt wird.", .ja: "変更はすべて元に戻せます。ショートカットは下で設定できます。このページには、実際の文章に触れる前に試せる入力欄もあります。", .zh: "任何改动都可以撤销——快捷键在下方设置。本页还有一个试用输入框，可以在它接触真实文字之前先试一试。", .pt: "Qualquer mudança pode ser desfeita — o atalho se configura abaixo. E nesta página há um campo para experimentar antes de tocar em algo real."]) }
    static var introStart: String { L("Got it", [.ru: "Понятно", .es: "Entendido", .fr: "Compris", .de: "Verstanden", .ja: "了解", .zh: "明白了", .pt: "Entendi"]) }
    static var tryIt: String { L("Try it", [.ru: "Попробовать", .es: "Pruébalo", .fr: "Essayer", .de: "Ausprobieren", .ja: "試す", .zh: "试一试", .pt: "Experimente"]) }
    static var tryItPlaceholder: String { L("Type ghbdtn and press space", [.ru: "Наберите ghbdtn и нажмите пробел", .es: "Escribe ghbdtn y pulsa espacio", .fr: "Tapez ghbdtn puis espace", .de: "Tippe ghbdtn und drücke die Leertaste", .ja: "ghbdtn と入力してスペースを押してください", .zh: "输入 ghbdtn 后按空格", .pt: "Digite ghbdtn e aperte espaço"]) }
    static var tryItHint: String { L("This is the real thing, not a demonstration: it works here exactly as it does anywhere else.", [.ru: "Поле настоящее, а не демонстрация: здесь модуль работает точно так же, как в любой другой программе.", .es: "El campo es real, no una demostración: aquí funciona igual que en cualquier otra app.", .fr: "Ce champ est réel, pas une démonstration : le module s’y comporte comme partout ailleurs.", .de: "Das Feld ist echt, keine Vorführung: hier arbeitet das Modul genau wie überall sonst.", .ja: "これはデモではなく本物の入力欄です。ここでも他のアプリと同じように動きます。", .zh: "这是真实的输入框，不是演示：它在这里的行为和在别处完全一样。", .pt: "O campo é real, não uma demonstração: aqui o módulo funciona como em qualquer outro app."]) }
    static var indicator: String { L("Language indicator", [.ru: "Индикатор языка", .es: "Indicador de idioma", .fr: "Indicateur de langue", .de: "Sprachanzeige", .ja: "入力ソース表示", .zh: "语言指示器", .pt: "Indicador de idioma"]) }
    static var indicatorShow: String { L("Show it in the menu bar", [.ru: "Показывать в строке меню", .es: "Mostrarlo en la barra de menús", .fr: "L’afficher dans la barre des menus", .de: "In der Menüleiste anzeigen", .ja: "メニューバーに表示", .zh: "在菜单栏中显示", .pt: "Mostrar na barra de menus"]) }
    static var indicatorHint: String { L("Helm's own copy of the menu-bar indicator, with the choices the system's one does not offer. macOS shows its own — turn that one off in Keyboard settings, or you get two.", [.ru: "Своя копия индикатора в строке меню — с настройками, которых нет у системного. Системный никуда не девается: выключите его в настройках клавиатуры, иначе их будет два.", .es: "Una copia propia del indicador con las opciones que el del sistema no ofrece. El del sistema sigue ahí: desactívalo en Ajustes de teclado o tendrás dos.", .fr: "Une copie de l’indicateur avec les choix que celui du système n’offre pas. Celui du système reste : désactivez-le dans les réglages du clavier, sinon vous en aurez deux.", .de: "Eine eigene Kopie der Anzeige, mit den Optionen, die die des Systems nicht bietet. Die des Systems bleibt: Schalte sie in den Tastatur-Einstellungen aus, sonst hast du zwei.", .ja: "システムの入力ソース表示を、設定できる形で複製したものです。システム側は残るので、キーボード設定でオフにしないと2つ並びます。", .zh: "菜单栏指示器的自有副本，带有系统版本没有的选项。系统的那个仍在：请在键盘设置中关闭，否则会有两个。", .pt: "Uma cópia própria do indicador, com as opções que o do sistema não oferece. O do sistema continua: desative-o nos Ajustes de teclado, ou você terá dois."]) }
    static var tapKey: String { L("One key for both", [.ru: "Одна клавиша на оба действия", .es: "Una tecla para ambos", .fr: "Une touche pour les deux", .de: "Eine Taste für beides", .ja: "ひとつのキーで両方", .zh: "一个键完成两件事", .pt: "Uma tecla para ambos"]) }
    static var tapKeyHint: String { L("Press and release it on its own: the first tap fixes the last word, the next puts it back. Held down or pressed with anything else it is still an ordinary modifier, so nothing you already use it for stops working.", [.ru: "Нажмите и отпустите её, ничего больше не нажимая: первое нажатие исправляет последнее слово, второе возвращает как было. Зажатая или нажатая вместе с чем-то ещё, она остаётся обычным модификатором — всё, для чего вы её уже используете, продолжает работать.", .es: "Púlsala y suéltala sola: la primera vez corrige la última palabra, la siguiente la devuelve. Mantenida o pulsada con otra tecla sigue siendo un modificador normal, así que nada de lo que ya haces con ella deja de funcionar.", .fr: "Appuyez puis relâchez-la seule : la première fois corrige le dernier mot, la suivante le restaure. Maintenue ou combinée, elle reste un modificateur ordinaire — rien de ce que vous en faites déjà ne cesse de fonctionner.", .de: "Allein drücken und loslassen: das erste Mal korrigiert das letzte Wort, das nächste stellt es zurück. Gehalten oder mit etwas anderem gedrückt bleibt sie ein gewöhnlicher Modifikator — nichts, wofür du sie schon benutzt, hört auf zu funktionieren.", .ja: "単独で押して離します。1 回目で直前の単語を修正し、もう一度で元に戻します。押しっぱなしや他のキーとの同時押しでは通常の修飾キーのままなので、いつもの使い方はそのまま生きています。", .zh: "单独按下再松开：第一次修正上一个词，再按一次还原。按住不放或与其他键同时按下时，它仍是普通的修饰键——你原有的用法不受影响。", .pt: "Pressione e solte sozinha: a primeira vez corrige a última palavra, a seguinte desfaz. Segurada ou junto com outra tecla, continua sendo um modificador comum — nada do que você já faz com ela deixa de funcionar."]) }
    static func tapKeyName(_ key: TapKey) -> String {
        switch key {
